package practice;

import java.util.List;

/**
 * Checkout shows the merchant's customer the cheapest way to pay. Which rules a merchant offers is
 * set per merchant: some offer only part of the standard methods, and some have negotiated rates
 * of their own, loaded from their contracts.
 */
public class Checkout {

    /** What a way of paying costs the merchant. */
    public interface FeeRule {
        long fee(long amountCents);

        String label();
    }

    /** The standard methods every merchant can offer. */
    public enum PaymentMethod implements FeeRule {
        CARD("card", 25, 240),
        BANK_TRANSFER("bank transfer", 40, 0),
        WALLET("wallet", 0, 310);

        private final String label;
        private final long fixedCents;
        private final int basisPoints;

        PaymentMethod(String label, long fixedCents, int basisPoints) {
            this.label = label;
            this.fixedCents = fixedCents;
            this.basisPoints = basisPoints;
        }

        @Override
        public long fee(long amountCents) {
            return fixedCents + amountCents * basisPoints / 10_000;
        }

        @Override
        public String label() {
            return label;
        }
    }

    /** A rate one merchant negotiated, read from its contract. */
    public record NegotiatedRate(String label, long fixedCents, int basisPoints) implements FeeRule {
        @Override
        public long fee(long amountCents) {
            return fixedCents + amountCents * basisPoints / 10_000;
        }
    }

    /**
     * The rule among {@code offered} with the lowest fee for {@code amountCents}.
     * {@code offered} is never empty.
     */
    public static FeeRule cheapest(List<? extends FeeRule> offered, long amountCents) {
        FeeRule best = offered.get(0);
        for (FeeRule rule : offered) {
            if (rule.fee(amountCents) < best.fee(amountCents)) best = rule;
        }
        return best;
    }
}

package practice;

import java.util.List;
import java.util.logging.ConsoleHandler;
import java.util.logging.Level;
import java.util.logging.Logger;

/** Run executes this file. Change the calls in main and see what prints. Submit grades. */
public class TryIt {
    /** Held here, so the JDK's own exit notice stays off: a logger nothing holds can be dropped. */
    private static final Logger JDK_EXIT = Logger.getLogger("java.lang.Runtime");

    public static void main(String[] args) {
        // Turn the logger up, so the log lines of your code show under the printed lines.
        System.setProperty("java.util.logging.SimpleFormatter.format", "%4$s %5$s%n");
        // Only this handler prints, and it leaves out the JDK's own detail.
        Logger root = Logger.getLogger("");
        for (java.util.logging.Handler before : root.getHandlers()) {
            root.removeHandler(before);
        }
        ConsoleHandler handler = new ConsoleHandler();
        handler.setLevel(Level.ALL);
        handler.setFilter(entry -> !String.valueOf(entry.getLoggerName()).matches("(java|javax|jdk|sun|com\\.sun)\\..*"));
        root.setLevel(Level.ALL);
        root.addHandler(handler);
        JDK_EXIT.setLevel(Level.OFF);

        // A stand-in for the collaborator, like the one the tests use for the first main case.
        try {
            List<Checkout.PaymentMethod> all = List.of(Checkout.PaymentMethod.values());
            System.out.println("all methods, 1,200 cents: " + Checkout.cheapest(all, 1_200).label());
            System.out.println("all methods, 25,000 cents: " + Checkout.cheapest(all, 25_000).label());
            List<Checkout.PaymentMethod> noTransfer = List.of(Checkout.PaymentMethod.CARD, Checkout.PaymentMethod.WALLET);
            System.out.println("no bank transfer, 25,000 cents: " + Checkout.cheapest(noTransfer, 25_000).label());
            Checkout.NegotiatedRate contract = new Checkout.NegotiatedRate("card, Corner Cafe rate", 5, 120);
            List<Checkout.FeeRule> offered = List.of(Checkout.PaymentMethod.WALLET, contract, Checkout.PaymentMethod.CARD);
            System.out.println("with negotiated rate, 4,000 cents: " + Checkout.cheapest(offered, 4_000).label());
        } catch (RuntimeException stopped) {
            // A method you have not finished, or a bug, stops here with its message, not a build error.
            System.out.println("Run stopped: " + stopped);
        }
    }
}

